create table if not exists catalog_pillars (
    id bigint generated by default as identity primary key,
    code text not null unique check (code in ('renforcement', 'cardio', 'proprioception')),
    label text not null,
    updated_at timestamptz not null
);
create table if not exists catalog_families (
    id bigint generated by default as identity primary key,
    code text not null unique,
    label text not null,
    updated_at timestamptz not null
);
create table if not exists catalog_types (
    id bigint generated by default as identity primary key,
    code text not null unique,
    label text not null,
    updated_at timestamptz not null
);
create table if not exists catalog_muscle_groups (
    id bigint generated by default as identity primary key,
    code text not null unique,
    label text not null,
    updated_at timestamptz not null
);
create table if not exists catalog_exercises (
    id bigint generated by default as identity primary key,
    code text not null unique,
    name text not null,
    pillar_id bigint not null references catalog_pillars(id) on delete restrict,
    family_id bigint not null references catalog_families(id) on delete restrict,
    type_id bigint not null references catalog_types(id) on delete restrict,
    level_min smallint not null check (level_min between 1 and 10),
    level_max smallint not null check (level_max >= level_min and level_max <= 10),
    equipment text not null,
    impact text check (impact is null or impact in ('faible', 'modere', 'eleve')),
    regression text,
    progression text not null default '',
    description text not null,
    start_position_steps jsonb not null default '[]'::jsonb,
    outbound_execution_steps jsonb not null default '[]'::jsonb,
    return_execution_steps jsonb not null default '[]'::jsonb,
    position_steps jsonb not null default '[]'::jsonb,
    execution_steps jsonb not null default '[]'::jsonb,
    common_errors jsonb not null default '[]'::jsonb,
    is_active boolean not null default true,
    review_status text not null default 'a_verifier' check (review_status in ('a_verifier', 'valide', 'a_revoir')),
    source_status text not null,
    updated_at timestamptz not null
);
create table if not exists catalog_exercise_muscle_groups (
    exercise_id bigint not null references catalog_exercises(id) on delete cascade,
    muscle_group_id bigint not null references catalog_muscle_groups(id) on delete cascade,
    primary key (exercise_id, muscle_group_id)
);
create table if not exists catalog_series (
    id bigint generated by default as identity primary key,
    code text not null unique,
    label text not null,
    series integer not null check (series >= 0),
    updated_at timestamptz not null
);
create table if not exists catalog_repetitions (
    id bigint generated by default as identity primary key,
    code text not null unique,
    label text not null,
    reps integer check (reps is null or reps >= 0),
    repetition_kind text not null check (repetition_kind in ('fixed', 'maximum')),
    updated_at timestamptz not null
);
create table if not exists catalog_rests (
    id bigint generated by default as identity primary key,
    code text not null unique,
    label text not null,
    rest_seconds integer not null check (rest_seconds >= 0),
    updated_at timestamptz not null
);
create table if not exists catalog_intervals (
    id bigint generated by default as identity primary key,
    code text not null unique,
    label text not null,
    effort_seconds integer not null check (effort_seconds >= 0),
    interval_kind text not null check (interval_kind in ('maximum_reps', 'controlled_reps', 'hold_position')),
    updated_at timestamptz not null
);
create table if not exists catalog_formats (
    id bigint generated by default as identity primary key,
    code text not null unique,
    format_type text not null check (format_type in ('repetitions', 'temps')),
    pillar_id bigint references catalog_pillars(id) on delete restrict,
    series_id bigint references catalog_series(id) on delete restrict,
    repetitions_id bigint references catalog_repetitions(id) on delete restrict,
    rest_id bigint references catalog_rests(id) on delete restrict,
    interval_id bigint references catalog_intervals(id) on delete restrict,
    label text not null,
    description text not null default '',
    series_count integer check (series_count is null or series_count > 0),
    execution_count integer check (execution_count is null or execution_count > 0),
    rest_series_seconds integer check (rest_series_seconds is null or rest_series_seconds >= 0),
    series_duration_seconds integer check (series_duration_seconds is null or series_duration_seconds >= 0),
    execution_duration_seconds integer check (execution_duration_seconds is null or execution_duration_seconds >= 0),
    rest_execution_seconds integer check (rest_execution_seconds is null or rest_execution_seconds >= 0),
    source_status text not null,
    updated_at timestamptz not null
);
create table if not exists catalog_session_definitions (
    id bigint generated by default as identity primary key,
    exercise_id bigint not null references catalog_exercises(id) on delete cascade,
    format_id bigint not null references catalog_formats(id) on delete cascade,
    level smallint not null check (level between 1 and 10),
    is_recommended boolean not null default true,
    sort_order integer not null default 0,
    source_reason text not null default '',
    updated_at timestamptz not null,
    unique (exercise_id, format_id, level)
);
create table if not exists catalog_seance_templates (
    id bigint generated by default as identity primary key,
    code text not null unique,
    title text not null,
    description text not null default '',
    pillar_id bigint not null references catalog_pillars(id) on delete restrict,
    duration_minutes integer not null check (duration_minutes > 0),
    sort_order integer not null default 0,
    is_active boolean not null default true,
    source_status text not null,
    updated_at timestamptz not null
);
create table if not exists catalog_level_seance_templates (
    pillar_id bigint not null references catalog_pillars(id) on delete cascade,
    level smallint not null check (level between 1 and 10),
    seance_template_id bigint not null references catalog_seance_templates(id) on delete cascade,
    is_recommended boolean not null default true,
    sort_order integer not null default 0,
    source_reason text not null default '',
    updated_at timestamptz not null,
    primary key (pillar_id, level, seance_template_id)
);
create table if not exists catalog_seance_template_sessions (
    seance_template_id bigint not null references catalog_seance_templates(id) on delete cascade,
    session_definition_id bigint not null references catalog_session_definitions(id) on delete cascade,
    sort_order integer not null default 0,
    source_reason text not null default '',
    updated_at timestamptz not null,
    primary key (seance_template_id, session_definition_id)
);
create index if not exists catalog_exercises_pillar_level_range_idx on catalog_exercises (pillar_id, level_min, level_max, name);
create index if not exists catalog_exercises_family_idx on catalog_exercises (family_id, name);
create index if not exists catalog_exercises_type_idx on catalog_exercises (type_id, name);
create index if not exists catalog_families_label_idx on catalog_families (label);
create index if not exists catalog_types_label_idx on catalog_types (label);
create index if not exists catalog_muscle_groups_label_idx on catalog_muscle_groups (label);
create index if not exists catalog_exercise_muscle_groups_group_idx on catalog_exercise_muscle_groups (muscle_group_id);
create index if not exists catalog_series_value_idx on catalog_series (series, label);
create index if not exists catalog_repetitions_kind_idx on catalog_repetitions (repetition_kind, reps, label);
create index if not exists catalog_rests_seconds_idx on catalog_rests (rest_seconds, label);
create index if not exists catalog_intervals_kind_idx on catalog_intervals (interval_kind, effort_seconds, label);
create index if not exists catalog_formats_type_idx on catalog_formats (format_type, label);
create index if not exists catalog_formats_pillar_idx on catalog_formats (pillar_id, format_type, label);
create index if not exists catalog_session_definitions_format_idx on catalog_session_definitions (format_id, level);
create index if not exists catalog_seance_templates_pillar_idx on catalog_seance_templates (pillar_id, sort_order, title);
create index if not exists catalog_level_seance_templates_template_idx on catalog_level_seance_templates (seance_template_id, sort_order);
create index if not exists catalog_seance_template_sessions_definition_idx on catalog_seance_template_sessions (session_definition_id, sort_order);
