insert into catalog_formats (code, format_type, pillar_id, series_id, repetitions_id, rest_id, interval_id, label, description, series_count, execution_count, rest_series_seconds, series_duration_seconds, execution_duration_seconds, rest_execution_seconds, source_status, updated_at)
select seed.code, seed.format_type, pillar.id, series.id, repetition.id, rest.id, interval.id, seed.label, seed.description, seed.series_count, seed.execution_count, seed.rest_series_seconds, seed.series_duration_seconds, seed.execution_duration_seconds, seed.rest_execution_seconds, seed.source_status, seed.updated_at
from seed
left join catalog_pillars pillar on pillar.code = seed.pillar_code
left join catalog_series series on series.code = seed.series_code
left join catalog_repetitions repetition on repetition.code = seed.repetitions_code
left join catalog_rests rest on rest.code = seed.rest_code
left join catalog_intervals interval on interval.code = seed.interval_code
on conflict (code) do update set
    format_type = excluded.format_type,
    pillar_id = excluded.pillar_id,
    series_id = excluded.series_id,
    repetitions_id = excluded.repetitions_id,
    rest_id = excluded.rest_id,
    interval_id = excluded.interval_id,
    label = excluded.label,
    description = excluded.description,
    series_count = excluded.series_count,
    execution_count = excluded.execution_count,
    rest_series_seconds = excluded.rest_series_seconds,
    series_duration_seconds = excluded.series_duration_seconds,
    execution_duration_seconds = excluded.execution_duration_seconds,
    rest_execution_seconds = excluded.rest_execution_seconds,
    source_status = excluded.source_status,
    updated_at = excluded.updated_at
where catalog_formats.source_status like 'seed%';

