insert into catalog_session_definitions (exercise_id, format_id, level, is_recommended, sort_order, source_reason, updated_at)
select exercise.id, format.id, seed.level, seed.is_recommended, seed.sort_order, seed.source_reason, seed.updated_at
from seed
join catalog_exercises exercise on exercise.code = seed.exercise_code
join catalog_formats format on format.code = seed.format_code
on conflict (exercise_id, format_id, level) do update set
    is_recommended = excluded.is_recommended,
    sort_order = excluded.sort_order,
    source_reason = excluded.source_reason,
    updated_at = excluded.updated_at
where catalog_session_definitions.source_reason not like 'Association admin%';
